class Solution {
    public: int maximalNetworkRank(int n,vector<vector<int>>& roads){
        vector<int> degree(n);
        vector<vector<bool>> connected(n,vector<bool>(n));
        for(auto& road:roads){
            ++degree[road[0]];
            ++degree[road[1]];
            connected[road[0]][road[1]]=connected[road[1]][road[0]]=true;
        }
        int answer=0;
        for(int first=0;first<n;++first)for(int second=first+1;second<n;++second)answer=max(answer,degree[first]+degree[second]-connected[first][second]);
        return answer;
    }
};
